-- Install the initial item catalogue (ItemCatalogEntry) for goods-first booking.
--
-- INSERT-ONLY, and deliberately so. The catalogue is edited in place from the
-- admin back office, so this migration must never overwrite a row: every insert
-- is ON CONFLICT ("code") DO NOTHING. On a database where a row already exists
-- (an earlier run, or an admin-added entry with the same code) it is a no-op,
-- and re-running the whole file changes nothing.
--
-- These rows are NOT in prisma/seed.ts's upsert path, for the same reason as
-- 20260904090000_backfill_vehicle_body_types: the seed's update branch rewrites
-- every field back to its constants and would discard ops' tuning. The rows
-- travel with `prisma migrate deploy` instead, in every environment.
--
-- Ids: gen_random_uuid()::text. Prisma's cuid() default is applied client-side
-- and does not exist in SQL; the id column is plain TEXT and nothing parses it.
-- "updatedAt" has no database default (Prisma's @updatedAt is client-side), so
-- it is set explicitly.
--
-- Figures are the item AS TRANSPORTED (lying down / dismantled where that is how
-- it travels), in kg and metres, length >= width, every value inside
-- CARGO_MEASUREMENT_BOUNDS (src/lib/cargo.ts). The fit check never rotates, so
-- upright-only items carry their standing height and the UPRIGHT_ONLY tag.
--
-- AWAITING REVIEW — see specs/goods-first-booking/action-required.md:
--   * "labelKa" and "synonymsKa" are first drafts and need a native speaker.
--   * Small DIY building items (plasterboard, tiles, paint, doors, windows) are
--     RETAIL_STOCK, not CONSTRUCTION_MATERIALS, so one paint bucket in a home
--     move does not force a heavy-only vehicle category. Ops to sign off.

INSERT INTO "ItemCatalogEntry" (
  "id", "code", "group", "labelEn", "labelKa", "synonymsEn", "synonymsKa",
  "weightKg", "lengthM", "widthM", "heightM", "stackable", "needsTwoPeople",
  "requiredBody", "handlingTags", "cargoCategory", "sortOrder", "active",
  "createdAt", "updatedAt"
) VALUES
